local StoneLintelMaker = {}
local PRODUCTS = {
    simple_stone_lintel = { name = "Preprost kamniti preklad", stoneCost = 3, time = 4, cost = 60, defense = 14, happiness = 1, description = "Preprost kamniti preklad za okna." },
    carved_limestone_lintel = { name = "Izrezljan apnenčni preklad", stoneCost = 3, paintCost = 1, time = 7, cost = 180, defense = 22, happiness = 2, prestige = 2, description = "Izrezljan apnenčni preklad za trgovce." },
    marble_relief_lintel = { name = "Marmornat reliefni preklad", marbleCost = 2, stoneCost = 1, paintCost = 1, time = 10, cost = 440, defense = 32, happiness = 2, prestige = 6, description = "Marmornat reliefni preklad za plemiče." },
    silver_trimmed_lintel = { name = "Srebrnoobrobljeni preklad", marbleCost = 2, silverCost = 1, stoneCost = 1, paintCost = 1, time = 14, cost = 1000, defense = 42, happiness = 3, prestige = 14, description = "Srebrnoobrobljeni preklad za visoke plemiče." },
    gold_inlaid_lintel = { name = "Zlatovloženi preklad", marbleCost = 2, goldCost = 1, silverCost = 1, stoneCost = 1, paintCost = 1, jewelCost = 1, time = 18, cost = 2300, defense = 54, happiness = 5, prestige = 27, description = "Preklad z draguljem za visoko plemstvo." },
    royal_grand_lintel = { name = "Kraljevski veliki preklad", marbleCost = 3, goldCost = 2, silverCost = 2, stoneCost = 1, paintCost = 1, jewelCost = 2, pearlCost = 2, time = 25, cost = 5000, defense = 68, happiness = 12, prestige = 58, description = "Veliki kraljevski preklad z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    lintel_workshop = { name = "Prekladna delavnica", cost = { gold = 240, wood = 100, stone = 160 }, upkeep = 5, qualityBonus = 5 },
    mason_loft = { name = "Zidarska podstrešje", cost = { gold = 880, wood = 240, stone = 320, marble = 4, silver = 6 }, upkeep = 20, qualityBonus = 18 },
    master_mason_atelier = { name = "Mojstrski zidarski atelje", cost = { gold = 2500, wood = 360, stone = 520, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_mason_palace = { name = "Kraljevska zidarska palača", cost = { gold = 10500, wood = 580, stone = 800, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
StoneLintelMaker.stoneStock = 18; StoneLintelMaker.marbleStock = 10; StoneLintelMaker.paintStock = 10; StoneLintelMaker.silverStock = 6; StoneLintelMaker.goldStock = 6; StoneLintelMaker.jewelStock = 4; StoneLintelMaker.pearlStock = 4
StoneLintelMaker.productStock = {}; StoneLintelMaker.buildings = {}; StoneLintelMaker.maker = nil; StoneLintelMaker.activeMaking = {}; StoneLintelMaker.totalProducts = 0; StoneLintelMaker.dayTimer = 0
function StoneLintelMaker.init() StoneLintelMaker.stoneStock=18; StoneLintelMaker.marbleStock=10; StoneLintelMaker.paintStock=10; StoneLintelMaker.silverStock=6; StoneLintelMaker.goldStock=6; StoneLintelMaker.jewelStock=4; StoneLintelMaker.pearlStock=4; StoneLintelMaker.productStock={}; StoneLintelMaker.buildings={}; StoneLintelMaker.maker=nil; StoneLintelMaker.activeMaking={}; StoneLintelMaker.totalProducts=0; StoneLintelMaker.dayTimer=0; print("[StoneLintelMaker] Royal Stone Lintel Maker System initialized (6 products, 4 buildings)") end
function StoneLintelMaker.hireMaker(n,s) s=s or math.random(55,90); local c=520+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; StoneLintelMaker.maker={name=n or ("Prekldapresek "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Prekldapresek najet: %s (spretnost: %d)",StoneLintelMaker.maker.name,s),"success") end; return true end
function StoneLintelMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function StoneLintelMaker.build(id) local ok,e=StoneLintelMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(StoneLintelMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function StoneLintelMaker.getQualityBonus() local b=0; for _,bd in ipairs(StoneLintelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function StoneLintelMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.stoneCost and StoneLintelMaker.stoneStock<(d.stoneCost or 0) then return false,"Premalo kamna" end; if d.marbleCost and StoneLintelMaker.marbleStock<(d.marbleCost or 0) then return false,"Premalo marmorja" end; if d.paintCost and StoneLintelMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.silverCost and StoneLintelMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and StoneLintelMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and StoneLintelMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and StoneLintelMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #StoneLintelMaker.buildings==0 then return false,"Potrebna prekladna delavnica" end; if not StoneLintelMaker.maker then return false,"Potreben prekldapresek" end; return true end
function StoneLintelMaker.make(pt,qty) qty=qty or 1; local ok,e=StoneLintelMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.stoneCost then StoneLintelMaker.stoneStock=StoneLintelMaker.stoneStock-d.stoneCost*qty end; if d.marbleCost then StoneLintelMaker.marbleStock=StoneLintelMaker.marbleStock-d.marbleCost*qty end; if d.paintCost then StoneLintelMaker.paintStock=StoneLintelMaker.paintStock-d.paintCost*qty end; if d.silverCost then StoneLintelMaker.silverStock=StoneLintelMaker.silverStock-d.silverCost*qty end; if d.goldCost then StoneLintelMaker.goldStock=StoneLintelMaker.goldStock-d.goldCost*qty end; if d.jewelCost then StoneLintelMaker.jewelStock=StoneLintelMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then StoneLintelMaker.pearlStock=StoneLintelMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if StoneLintelMaker.maker then t=math.max(1,t-math.floor(StoneLintelMaker.maker.skill/13)) end; table.insert(StoneLintelMaker.activeMaking,{id="lintel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,defense=d.defense or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rezbarjenje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function StoneLintelMaker.completeMaking(m) local q=1.0+(StoneLintelMaker.getQualityBonus()/100); if StoneLintelMaker.maker then q=q+(StoneLintelMaker.maker.skill/140) end; q=math.min(2.5,q); StoneLintelMaker.productStock[m.productType]=(StoneLintelMaker.productStock[m.productType] or 0)+m.quantity; StoneLintelMaker.totalProducts=StoneLintelMaker.totalProducts+m.quantity; if m.defense>0 and _G.state then _G.state.defense=(_G.state.defense or 0)+m.defense end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if StoneLintelMaker.maker then StoneLintelMaker.maker.itemsMade=StoneLintelMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then StoneLintelMaker.maker.skill=math.min(100,StoneLintelMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Preklad izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"lintel.completed",{productName=m.productName,defense=m.defense,prestige=m.prestige,happiness=m.happiness}) end end
function StoneLintelMaker.update(dt) if not _G.state then return end; StoneLintelMaker.dayTimer=StoneLintelMaker.dayTimer+dt; if StoneLintelMaker.dayTimer>=30 then StoneLintelMaker.dayTimer=0; for i=#StoneLintelMaker.activeMaking,1,-1 do local m=StoneLintelMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then StoneLintelMaker.completeMaking(m); table.remove(StoneLintelMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(StoneLintelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if StoneLintelMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function StoneLintelMaker.getStats() return {stoneStock=StoneLintelMaker.stoneStock,marbleStock=StoneLintelMaker.marbleStock,paintStock=StoneLintelMaker.paintStock,silverStock=StoneLintelMaker.silverStock,goldStock=StoneLintelMaker.goldStock,jewelStock=StoneLintelMaker.jewelStock,pearlStock=StoneLintelMaker.pearlStock,productStock=StoneLintelMaker.productStock,numBuildings=#StoneLintelMaker.buildings,hasMaker=StoneLintelMaker.maker~=nil,makerName=StoneLintelMaker.maker and StoneLintelMaker.maker.name or "—",makerSkill=StoneLintelMaker.maker and StoneLintelMaker.maker.skill or 0,activeMaking=#StoneLintelMaker.activeMaking,totalProducts=StoneLintelMaker.totalProducts} end
return StoneLintelMaker
